32	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerTelephoneException;
33	import org.springframework.samples.petclinic.rest.controller.EmailNormalizer;
34	import org.springframework.samples.petclinic.rest.controller.OwnerCityCapacityExceededException;
35	import org.springframework.samples.petclinic.rest.controller.OwnerDailyRegistrationLimitExceededException;
36	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
37	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final OwnerFieldsValidator ownerFieldsValidator;
75	
76	    private final TelephoneNormalizer telephoneNormalizer;
77	
78	    private final EmailNormalizer emailNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    private final BusinessDayResolver businessDayResolver;
83	
84	    /** Maximum number of owners a single city may hold before further creations are rejected. */
85	    static final long MAX_OWNERS_PER_CITY = 50;
86	
87	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
88	    static final long MAX_OWNERS_PER_DAY = 100;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper,
94	                                 OwnerFieldsValidator ownerFieldsValidator,
95	                                 TelephoneNormalizer telephoneNormalizer,
96	                                 EmailNormalizer emailNormalizer,
97	                                 AddressNormalizer addressNormalizer,
98	                                 BusinessDayResolver businessDayResolver) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.ownerFieldsValidator = ownerFieldsValidator;
104	        this.telephoneNormalizer = telephoneNormalizer;
105	        this.emailNormalizer = emailNormalizer;
106	        this.addressNormalizer = addressNormalizer;
107	        this.businessDayResolver = businessDayResolver;
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
113	        Collection<Owner> owners;
114	        if (lastName != null) {
115	            owners = this.clinicService.findOwnerByLastName(lastName);
116	        } else {
117	            owners = this.clinicService.findAllOwners();
118	        }
119	        if (owners.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
139	        this.ownerFieldsValidator.validate(ownerFieldsDto);
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
143	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
144	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
145	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
146	        if (this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
147	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
148	        }
149	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
150	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
151	        }
152	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
153	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
154	        }
155	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
156	            this.clinicService.joinHousehold(owner);
157	        } else if (!this.clinicService.findOwnersInSameHousehold(owner.getLastName(), owner.getAddress()).isEmpty()) {
158	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
159	        }
160	        this.clinicService.saveOwner(owner);
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        currentOwner.setAddress(ownerFieldsDto.getAddress());
175	        currentOwner.setCity(ownerFieldsDto.getCity());
176	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	        currentOwner.setLastName(ownerFieldsDto.getLastName());
178	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
179	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
180	        this.clinicService.saveOwner(currentOwner);
181	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Transactional
186	    @Override
187	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        this.clinicService.deleteOwner(owner);
193	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
199	        Owner owner = this.clinicService.findOwnerById(ownerId);
200	        if (owner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        HttpHeaders headers = new HttpHeaders();
204	        Pet pet = petMapper.toPet(petFieldsDto);
205	        owner.setId(ownerId);
